// Live camera, microphone and screen sharing for Frame watch parties.
// WebRTC media is peer-to-peer; the existing WebSocket is used only for signaling/state.
const rtcState={socket:null,me:null,room:null,joined:false,localStream:null,screenStream:null,facing:'user',iceServers:[{urls:'stun:stun.l.google.com:19302'}],outAV:new Map(),inAV:new Map(),outScreen:new Map(),inScreen:new Map(),pendingIce:new Map(),media:{mic:false,camera:false,screen:false},spotlight:null};

function rtcToast(text){const t=document.getElementById('toast');if(!t)return;t.textContent=text;t.style.display='block';setTimeout(()=>{if(t.textContent===text)t.style.display='none'},5200)}
function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function sendRTC(type,data={}){if(rtcState.socket?.readyState===1)rtcState.socket.send(JSON.stringify({type,...data,actionId:crypto.randomUUID()}))}
function member(id){return rtcState.room?.members?.find(x=>x.id===id)}
function isHost(){return !!rtcState.room&&rtcState.room.host===rtcState.me}
function peers(){return (rtcState.room?.members||[]).filter(x=>x.id!==rtcState.me&&x.online)}

const css=document.createElement('style');
css.textContent=`
.live-call{margin:18px 0 4px;border:1px solid #303038;background:#17171d;border-radius:14px;padding:13px}.live-call-head{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.live-call-head strong{font:600 13px 'Space Grotesk',sans-serif;margin-right:auto}.call-controls{display:flex;gap:7px;flex-wrap:wrap}.call-controls button{font-size:11px;padding:8px 10px}.call-controls button.active{background:var(--lime);color:#1b2111;border-color:var(--lime)}.call-controls button.danger{border-color:#6f3d45;color:#ffb4bd}.rtc-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin-top:12px;transition:.25s}.rtc-grid.cinema{grid-template-columns:repeat(auto-fit,minmax(125px,170px))}.rtc-tile{position:relative;overflow:hidden;background:#09090c;border:1px solid #303038;border-radius:12px;aspect-ratio:16/10;min-height:110px}.rtc-tile.spotlight{grid-column:span 2;grid-row:span 2}.rtc-tile video{width:100%;height:100%;object-fit:cover;background:#080809}.rtc-tile.local video{transform:scaleX(-1)}.rtc-tile.screen-tile video{object-fit:contain;transform:none}.rtc-label{position:absolute;left:8px;bottom:7px;background:#0b0b0ecc;border:1px solid #ffffff18;border-radius:999px;padding:5px 8px;font-size:10px}.rtc-badges{position:absolute;right:7px;top:7px;display:flex;gap:5px}.rtc-badge{background:#0b0b0ecc;border:1px solid #ffffff18;border-radius:999px;padding:4px 6px;font-size:9px}.rtc-host-tools{position:absolute;right:7px;bottom:7px;display:flex;gap:5px;opacity:0;transition:.18s}.rtc-tile:hover .rtc-host-tools{opacity:1}.rtc-host-tools button{font-size:9px;padding:5px 7px;background:#17171de8}.rtc-empty{color:#858590;font-size:11px;padding:12px 2px 3px}.rtc-screen-zone{margin-top:10px}.rtc-screen-zone h4{margin:0 0 8px;font-size:11px;color:#b8b8c2;font-weight:500}.screen-share-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px}.screen-share-grid:empty{display:none}@media(max-width:700px){.rtc-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.rtc-grid.cinema{grid-template-columns:repeat(2,minmax(0,1fr))}.rtc-tile.spotlight{grid-column:1/-1;grid-row:auto}.screen-share-grid{grid-template-columns:1fr}}
`;
document.head.appendChild(css);

const anchor=document.querySelector('.room-actions');
const panel=document.createElement('section');panel.className='live-call';panel.innerHTML=`
 <div class="live-call-head"><strong>● Live lounge <span id="rtcCount" style="color:#8d8d99;font-weight:400"></span></strong><div class="call-controls">
 <button id="joinLive">📹 Join live</button><button id="rtcMic" disabled>🎙 Mic</button><button id="rtcCam" disabled>📷 Camera</button><button id="rtcFlip" disabled>↺ Camera</button><button id="rtcScreen" disabled>🖥 Share screen</button><button id="rtcLeave" class="danger" disabled>Leave call</button>
 </div></div><div id="rtcEmpty" class="rtc-empty">Join live to talk, turn on camera, or share your screen while the movie stays synced.</div><div id="rtcGrid" class="rtc-grid"></div><div class="rtc-screen-zone"><h4 id="screenTitle" hidden>Shared screens</h4><div id="screenGrid" class="screen-share-grid"></div></div>`;
anchor?.insertAdjacentElement('afterend',panel);
const $r=id=>document.getElementById(id),grid=$r('rtcGrid'),screenGrid=$r('screenGrid');

async function loadIceConfig(){try{const r=await fetch('/rtc-config',{cache:'no-store'});if(r.ok){const d=await r.json();if(Array.isArray(d.iceServers)&&d.iceServers.length)rtcState.iceServers=d.iceServers}}catch{}}
loadIceConfig();

function updateControls(){
 $r('joinLive').disabled=rtcState.joined;$r('rtcLeave').disabled=!rtcState.joined;$r('rtcMic').disabled=!rtcState.joined;$r('rtcCam').disabled=!rtcState.joined;$r('rtcScreen').disabled=!rtcState.joined;$r('rtcFlip').disabled=!rtcState.joined||!rtcState.media.camera;
 $r('rtcMic').classList.toggle('active',rtcState.media.mic);$r('rtcCam').classList.toggle('active',rtcState.media.camera);$r('rtcScreen').classList.toggle('active',rtcState.media.screen);
 $r('rtcMic').textContent=rtcState.media.mic?'🎙 Mic on':'🔇 Mic off';$r('rtcCam').textContent=rtcState.media.camera?'📷 Camera on':'📷 Camera off';$r('rtcScreen').textContent=rtcState.media.screen?'🖥 Stop sharing':'🖥 Share screen';
 $r('rtcEmpty').hidden=rtcState.joined||grid.children.length>0;$r('rtcCount').textContent=rtcState.room?`· ${(rtcState.room.members||[]).filter(m=>m.media?.joined).length} live`:'';
 grid.classList.toggle('cinema',!!rtcState.room?.playback?.playing);
}

function ensureTile(id,name,local=false){let tile=grid.querySelector(`[data-peer="${CSS.escape(id)}"]`);if(tile)return tile;tile=document.createElement('article');tile.className='rtc-tile'+(local?' local':'');tile.dataset.peer=id;tile.innerHTML=`<video autoplay playsinline ${local?'muted':''}></video><span class="rtc-label">${esc(name)}${local?' · you':''}</span><div class="rtc-badges"></div><div class="rtc-host-tools"></div>`;grid.appendChild(tile);return tile}
function updateTileBadges(id){const tile=grid.querySelector(`[data-peer="${CSS.escape(id)}"]`);if(!tile)return;const m=id===rtcState.me?{media:{...rtcState.media}}:member(id);const media=m?.media||{};const badges=tile.querySelector('.rtc-badges');badges.innerHTML=`${media.mic===false?'<span class="rtc-badge">🔇</span>':''}${media.camera===false?'<span class="rtc-badge">📷 off</span>':''}`;tile.classList.toggle('spotlight',rtcState.spotlight===id);const tools=tile.querySelector('.rtc-host-tools');if(isHost()&&id!==rtcState.me){tools.innerHTML=`<button data-host-mute="${id}">Mute</button><button data-host-cam="${id}">Cam off</button><button data-spot="${id}">${rtcState.spotlight===id?'Unspot':'★ Spotlight'}</button>`}else if(isHost()&&id===rtcState.me){tools.innerHTML=`<button data-spot="${id}">${rtcState.spotlight===id?'Unspot':'★ Spotlight'}</button>`}else tools.innerHTML=''}
function attachStream(id,stream,name,local=false){const tile=ensureTile(id,name,local),v=tile.querySelector('video');if(v.srcObject!==stream)v.srcObject=stream;v.muted=local;v.play().catch(()=>{});updateTileBadges(id)}
function removeTile(id){grid.querySelector(`[data-peer="${CSS.escape(id)}"]`)?.remove()}
function screenTileId(id){return `screen-${id}`}
function attachScreen(id,stream,name,local=false){let tile=screenGrid.querySelector(`[data-screen-peer="${CSS.escape(id)}"]`);if(!tile){tile=document.createElement('article');tile.className='rtc-tile screen-tile'+(local?' local':'');tile.dataset.screenPeer=id;tile.innerHTML=`<video autoplay playsinline ${local?'muted':''}></video><span class="rtc-label">🖥 ${esc(name)}${local?' · you':''}</span>`;screenGrid.appendChild(tile)}const v=tile.querySelector('video');v.srcObject=stream;v.muted=local;v.play().catch(()=>{});$r('screenTitle').hidden=false}
function removeScreen(id){screenGrid.querySelector(`[data-screen-peer="${CSS.escape(id)}"]`)?.remove();$r('screenTitle').hidden=!screenGrid.children.length}

function pcKey(channel,id){return `${channel}:${id}`}
function queueIce(channel,id,candidate){const k=pcKey(channel,id),arr=rtcState.pendingIce.get(k)||[];arr.push(candidate);rtcState.pendingIce.set(k,arr)}
async function flushIce(channel,id,pc){const k=pcKey(channel,id),arr=rtcState.pendingIce.get(k)||[];rtcState.pendingIce.delete(k);for(const c of arr)try{await pc.addIceCandidate(c)}catch{}}
function makePC(target,channel,outgoing){const pc=new RTCPeerConnection({iceServers:rtcState.iceServers});pc.onicecandidate=e=>{if(e.candidate)sendRTC('rtc-ice',{target,channel,candidate:e.candidate})};pc.onconnectionstatechange=()=>{if(['failed','closed'].includes(pc.connectionState)){if(channel==='av')removeTile(target);else removeScreen(target)}};if(!outgoing){pc.ontrack=e=>{const stream=e.streams?.[0]||new MediaStream([e.track]);const m=member(target);if(channel==='screen')attachScreen(target,stream,m?.name||'Guest');else attachStream(target,stream,m?.name||'Guest')}}return pc}

async function createOutgoingAV(target){if(!rtcState.joined||!rtcState.localStream||rtcState.outAV.has(target))return;const pc=makePC(target,'av',true);for(const track of rtcState.localStream.getTracks())pc.addTrack(track,rtcState.localStream);rtcState.outAV.set(target,pc);const offer=await pc.createOffer();await pc.setLocalDescription(offer);sendRTC('rtc-offer',{target,channel:'av',sdp:pc.localDescription})}
async function createOutgoingScreen(target){if(!rtcState.screenStream||rtcState.outScreen.has(target))return;const pc=makePC(target,'screen',true);for(const track of rtcState.screenStream.getTracks())pc.addTrack(track,rtcState.screenStream);rtcState.outScreen.set(target,pc);const offer=await pc.createOffer();await pc.setLocalDescription(offer);sendRTC('rtc-offer',{target,channel:'screen',sdp:pc.localDescription})}
function connectToPeers(){for(const p of peers()){createOutgoingAV(p.id).catch(()=>{});if(rtcState.screenStream)createOutgoingScreen(p.id).catch(()=>{})}}

async function onOffer(from,channel,sdp){const map=channel==='screen'?rtcState.inScreen:rtcState.inAV;map.get(from)?.close();const pc=makePC(from,channel,false);map.set(from,pc);await pc.setRemoteDescription(sdp);await flushIce(channel,from,pc);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);sendRTC('rtc-answer',{target:from,channel,sdp:pc.localDescription})}
async function onAnswer(from,channel,sdp){const pc=(channel==='screen'?rtcState.outScreen:rtcState.outAV).get(from);if(!pc)return;await pc.setRemoteDescription(sdp);await flushIce(channel,from,pc)}
async function onIce(from,channel,candidate){const pc=(channel==='screen'?rtcState.inScreen:rtcState.inAV).get(from)||(channel==='screen'?rtcState.outScreen:rtcState.outAV).get(from);if(!pc||!pc.remoteDescription)return queueIce(channel,from,candidate);try{await pc.addIceCandidate(candidate)}catch{}}

function publishState(){sendRTC('rtc-state',{joined:rtcState.joined,mic:rtcState.media.mic,camera:rtcState.media.camera,screen:rtcState.media.screen})}
async function joinLive(){if(rtcState.joined)return;try{const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:{width:{ideal:1280},height:{ideal:720},facingMode:{ideal:rtcState.facing}}});rtcState.localStream=stream;rtcState.joined=true;rtcState.media={mic:true,camera:true,screen:false};attachStream(rtcState.me||'local',stream,member(rtcState.me)?.name||'You',true);publishState();connectToPeers();updateControls()}catch(e){rtcToast(e.name==='NotAllowedError'?'Camera/mic permission was blocked. Allow it in the browser and try again.':'Could not start camera/mic on this device.')}}
function closeMap(map){for(const pc of map.values())try{pc.close()}catch{}map.clear()}
function leaveLive(){stopScreen(false);for(const t of rtcState.localStream?.getTracks()||[])t.stop();rtcState.localStream=null;rtcState.joined=false;rtcState.media={mic:false,camera:false,screen:false};closeMap(rtcState.outAV);closeMap(rtcState.inAV);removeTile(rtcState.me||'local');publishState();updateControls()}
function toggleMic(){const track=rtcState.localStream?.getAudioTracks()[0];if(!track)return;track.enabled=!track.enabled;rtcState.media.mic=track.enabled;publishState();updateControls();updateTileBadges(rtcState.me)}
function toggleCam(){const track=rtcState.localStream?.getVideoTracks()[0];if(!track)return;track.enabled=!track.enabled;rtcState.media.camera=track.enabled;publishState();updateControls();updateTileBadges(rtcState.me)}
async function flipCamera(){if(!rtcState.joined)return;const old=rtcState.localStream?.getVideoTracks()[0];rtcState.facing=rtcState.facing==='user'?'environment':'user';try{const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:rtcState.facing},width:{ideal:1280},height:{ideal:720}},audio:false});const next=s.getVideoTracks()[0];next.enabled=rtcState.media.camera;for(const pc of rtcState.outAV.values()){const sender=pc.getSenders().find(x=>x.track?.kind==='video');if(sender)await sender.replaceTrack(next)}if(old){rtcState.localStream.removeTrack(old);old.stop()}rtcState.localStream.addTrack(next);attachStream(rtcState.me,rtcState.localStream,member(rtcState.me)?.name||'You',true)}catch{rtcState.facing=rtcState.facing==='user'?'environment':'user';rtcToast('Could not switch camera on this device.')}}
async function startScreen(){if(rtcState.screenStream)return stopScreen();try{const s=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:{ideal:30,max:30}},audio:true});rtcState.screenStream=s;rtcState.media.screen=true;attachScreen(rtcState.me,s,member(rtcState.me)?.name||'You',true);s.getVideoTracks()[0].addEventListener('ended',()=>stopScreen());publishState();for(const p of peers())createOutgoingScreen(p.id).catch(()=>{});updateControls()}catch(e){if(e.name!=='NotAllowedError')rtcToast('Screen sharing could not start.')}}
function stopScreen(publish=true){if(!rtcState.screenStream)return;for(const t of rtcState.screenStream.getTracks())t.stop();rtcState.screenStream=null;rtcState.media.screen=false;closeMap(rtcState.outScreen);removeScreen(rtcState.me);if(publish)publishState();updateControls()}

$r('joinLive').onclick=joinLive;$r('rtcLeave').onclick=leaveLive;$r('rtcMic').onclick=toggleMic;$r('rtcCam').onclick=toggleCam;$r('rtcFlip').onclick=flipCamera;$r('rtcScreen').onclick=startScreen;
panel.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.hostMute)sendRTC('rtc-command',{target:b.dataset.hostMute,command:'mute'});if(b.dataset.hostCam)sendRTC('rtc-command',{target:b.dataset.hostCam,command:'camera-off'});if(b.dataset.spot)sendRTC('rtc-spotlight',{target:rtcState.spotlight===b.dataset.spot?'':b.dataset.spot})});

function cleanupPeer(id){for(const map of [rtcState.outAV,rtcState.inAV,rtcState.outScreen,rtcState.inScreen]){map.get(id)?.close();map.delete(id)}removeTile(id);removeScreen(id)}
function handleCommand(command){if(command==='mute'){const t=rtcState.localStream?.getAudioTracks()[0];if(t)t.enabled=false;rtcState.media.mic=false;rtcToast('The room host muted your microphone.')}if(command==='camera-off'){const t=rtcState.localStream?.getVideoTracks()[0];if(t)t.enabled=false;rtcState.media.camera=false;rtcToast('The room host turned your camera off.')}publishState();updateControls();updateTileBadges(rtcState.me)}
function handleRoomState(data){const previous=new Set((rtcState.room?.members||[]).filter(x=>x.online).map(x=>x.id));rtcState.room=data;rtcState.spotlight=data.spotlight||null;const current=new Set((data.members||[]).filter(x=>x.online).map(x=>x.id));for(const id of previous)if(!current.has(id)&&id!==rtcState.me)cleanupPeer(id);if(rtcState.joined)connectToPeers();for(const m of data.members||[]){if(m.id===rtcState.me&&rtcState.joined)updateTileBadges(m.id);else if(m.media?.joined&&m.online){const tile=ensureTile(m.id,m.name,false);updateTileBadges(m.id);if(!tile.querySelector('video').srcObject)tile.querySelector('video').poster=''}else if(m.id!==rtcState.me&&!rtcState.inAV.has(m.id))removeTile(m.id);if(!m.media?.screen&&!rtcState.inScreen.has(m.id))removeScreen(m.id)}grid.querySelectorAll('.rtc-tile').forEach(t=>t.classList.toggle('spotlight',t.dataset.peer===rtcState.spotlight));updateControls()}

// enhancements-v3 creates the actual socket after this module is imported. Wrap its constructor and observe the same messages.
const BaseWS=window.WebSocket;
window.WebSocket=class FrameRTCWebSocket extends BaseWS{
 constructor(...args){super(...args);rtcState.socket=this;this.addEventListener('message',e=>{let d;try{d=JSON.parse(e.data)}catch{return}if(d.type==='welcome'){rtcState.me=d.id;if(rtcState.localStream)attachStream(d.id,rtcState.localStream,member(d.id)?.name||'You',true)}else if(d.type==='state')handleRoomState(d);else if(d.type==='rtc-offer')onOffer(d.from,d.channel,d.sdp).catch(()=>{});else if(d.type==='rtc-answer')onAnswer(d.from,d.channel,d.sdp).catch(()=>{});else if(d.type==='rtc-ice')onIce(d.from,d.channel,d.candidate).catch(()=>{});else if(d.type==='rtc-command')handleCommand(d.command)})}
};

window.addEventListener('beforeunload',()=>{try{leaveLive()}catch{}});updateControls();
